from connect import ConnectGame


class ConnectGameTests(unittest.TestCase):
    def test_empty_and_unconnected_boards(self):
        for board in ("", "   \n", ".", ". .\n . .", "X O\n O X"):
            with self.subTest(board=board):
                self.assertEqual(ConnectGame(board).get_winner(), "")

    def test_single_stone_boards(self):
        for player in ("X", "O"):
            with self.subTest(player=player):
                self.assertEqual(ConnectGame(player).get_winner(), player)

    def test_horizontal_x_connection_on_wide_board(self):
        board = "X X X X\n O . O ."
        self.assertEqual(ConnectGame(board).get_winner(), "X")

    def test_vertical_o_connection_on_tall_board(self):
        board = "O X\n O .\n  O X\n   O ."
        self.assertEqual(ConnectGame(board).get_winner(), "O")

    def test_up_right_and_down_left_are_neighbors(self):
        for board, winner in ((". X\n X .", "X"), (". O\n O .", "O")):
            with self.subTest(winner=winner):
                self.assertEqual(ConnectGame(board).get_winner(), winner)

    def test_down_right_is_not_a_neighbor(self):
        for player in ("X", "O"):
            with self.subTest(player=player):
                board = f"{player} .\n . {player}"
                self.assertEqual(ConnectGame(board).get_winner(), "")

    def test_wrong_sides_do_not_win(self):
        for board in ("O O O\n . . .", "X .\n X .\n X ."):
            with self.subTest(board=board):
                self.assertEqual(ConnectGame(board).get_winner(), "")

    def test_example_has_no_winner(self):
        board = ". O . X .\n . X X O .\n  O O O X .\n   . X O X O\n    X O O O X"
        self.assertEqual(ConnectGame(board).get_winner(), "")

    def test_searches_all_starting_stones(self):
        board = "X . . .\n . O O .\n X X X X"
        game = ConnectGame(board)
        self.assertEqual(game.get_winner(), "X")
        self.assertEqual(game.get_winner(), "X")

    def test_long_connection_does_not_require_recursion(self):
        self.assertEqual(ConnectGame(" ".join(["X"] * 2000)).get_winner(), "X")

    def test_cycles_without_a_connection(self):
        board = "X X .\n X X .\n . . ."
        self.assertEqual(ConnectGame(board).get_winner(), "")


if __name__ == "__main__":
    unittest.main()
